pub fn normalize_model_id(raw_model_id: &str) -> &'static str {
    let trimmed = raw_model_id.trim();
    if trimmed.is_empty() {
        return "~openai/gpt-mini-latest";
    }
    for (legacy, target) in LEGACY_MODEL_ALIASES {
        if *legacy == trimmed {
            return target;
        }
    }
    let without_tilde = trimmed.strip_prefix('~').unwrap_or(trimmed);
    for (legacy, target) in LEGACY_MODEL_ALIASES {
        if *legacy == without_tilde {
            return target;
        }
    }
    for model in CANONICAL_MODELS {
        if model.id == without_tilde || model.wire_model == trimmed {
            return model.wire_model;
        }
    }
    "~openai/gpt-mini-latest"
}

pub fn resolve_visual_route(
    surface: &str,
    _content_policy: &str,
) -> &'static VisualSurfaceRouteDescriptor {
    for route in VISUAL_SURFACE_ROUTES {
        if route.surface == surface {
            return route;
        }
    }
    &VISUAL_SURFACE_ROUTES[1]
}

pub fn is_deepseek_off_peak_utc(utc_hour: u8, utc_minute: u8) -> bool {
    let total_mins = ((utc_hour as u16 % 24) * 60) + (utc_minute as u16 % 60);
    total_mins >= (16 * 60 + 30) || total_mins <= 30
}

pub fn wilson_score_lower_bound(successes: u64, total: u64, z: f64) -> f64 {
    if total == 0 {
        return 0.0;
    }
    let n = total as f64;
    let phat = (successes as f64 / n).clamp(0.0, 1.0);
    let z2 = z * z;
    let denom = 1.0 + z2 / n;
    let center = phat + z2 / (2.0 * n);
    let spread = z * ((phat * (1.0 - phat) + z2 / (4.0 * n)) / n).sqrt();
    ((center - spread) / denom).clamp(0.0, 1.0)
}

pub fn usd_to_nano(usd: f64) -> i64 {
    (usd * (NANO_USD_PER_USD as f64)).round() as i64
}

pub fn nano_to_usd(nano_usd: i64) -> f64 {
    (nano_usd as f64) / (NANO_USD_PER_USD as f64)
}

pub fn fuse_socrates_confidence(
    evidence_quality: f64,
    citation_coverage: f64,
    normalized_logprob: f64,
    semantic_entropy_inverse: f64,
    self_consistency: f64,
) -> (f64, &'static str) {
    let c = 0.15 * evidence_quality
        + 0.15 * citation_coverage
        + 0.30 * normalized_logprob
        + 0.20 * semantic_entropy_inverse
        + 0.20 * self_consistency;
    let action = if c >= 0.78 {
        "answer"
    } else if c >= 0.58 {
        "hedge_with_citations"
    } else if c >= 0.38 {
        "clarify"
    } else {
        "abstain"
    };
    (c, action)
}

pub fn compute_staleness_horizon(doc_path: &str, base_horizon_days: i32) -> (i32, i32) {
    let mut h: u32 = 0x811c9dc5;
    for b in doc_path.trim().to_ascii_lowercase().bytes() {
        h ^= b as u32;
        h = h.wrapping_mul(0x01000193);
    }
    let jitter_days = ((h % 15) as i32) - 7;
    let effective = (base_horizon_days + jitter_days).max(7);
    (jitter_days, effective)
}

pub fn evaluate_search_circuit_breaker(
    consecutive_failures: u32,
    base_delay_sec: u32,
    failure_threshold: u32,
) -> (&'static str, u32, bool) {
    let state = if consecutive_failures >= failure_threshold {
        "open"
    } else if consecutive_failures > 0 {
        "half_open"
    } else {
        "closed"
    };
    let cooldown = if consecutive_failures == 0 {
        0
    } else {
        base_delay_sec * (1u32 << consecutive_failures.min(4))
    };
    (state, cooldown, state == "open")
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct CvFlywheelSummary {
    pub visual_before_score: f64,
    pub visual_after_score: f64,
    pub visual_delta: f64,
    pub edge_sharpness_delta_pct: f64,
    pub contrast_delta_pct: f64,
    pub noise_reduction_pct: f64,
    pub estimated_psnr_db: f64,
    pub flywheel_converged: bool,
}

pub fn evaluate_before_after_cv_flywheel(
    before_rubric: (f64, f64, f64, f64, f64),
    after_rubric: (f64, f64, f64, f64, f64),
    before_signals: (f64, f64, f64),
    after_signals: (f64, f64, f64),
    after_grounded: bool,
) -> CvFlywheelSummary {
    let b_score = 0.25 * before_rubric.0
        + 0.30 * before_rubric.1
        + 0.20 * before_rubric.2
        + 0.15 * before_rubric.3
        + 0.10 * before_rubric.4;
    let a_score = 0.25 * after_rubric.0
        + 0.30 * after_rubric.1
        + 0.20 * after_rubric.2
        + 0.15 * after_rubric.3
        + 0.10 * after_rubric.4;
    let visual_delta = a_score - b_score;
    let b_edge = before_signals.0.max(1.0);
    let b_contrast = before_signals.1.max(1.0);
    let b_noise = before_signals.2.max(1.0);
    let edge_sharpness_delta_pct = ((after_signals.0 - b_edge) / b_edge) * 100.0;
    let contrast_delta_pct = ((after_signals.1 - b_contrast) / b_contrast) * 100.0;
    let noise_reduction_pct = ((b_noise - after_signals.2) / b_noise) * 100.0;
    let estimated_psnr_db = 28.0 + a_score * 11.0 + noise_reduction_pct.max(0.0) * 0.08;
    let flywheel_converged =
        a_score >= 0.74 && after_rubric.2 >= 0.60 && after_grounded && visual_delta >= 0.0;
    CvFlywheelSummary {
        visual_before_score: b_score,
        visual_after_score: a_score,
        visual_delta,
        edge_sharpness_delta_pct,
        contrast_delta_pct,
        noise_reduction_pct,
        estimated_psnr_db,
        flywheel_converged,
    }
}

pub fn select_model_for_task(
    task_tier: &str,
    gross_margin_pct: f64,
    is_guest: bool,
) -> (&'static str, &'static str, bool) {
    if is_guest || gross_margin_pct < 0.35 {
        return ("~openai/gpt-mini-latest", "free_or_local", true);
    }
    if task_tier == "frontier_reasoning" {
        return ("~anthropic/claude-opus-latest", "frontier_reasoning", false);
    }
    if task_tier == "balanced_production" {
        return (
            "~anthropic/claude-sonnet-latest",
            "balanced_production",
            false,
        );
    }
    ("~openai/gpt-mini-latest", "free_or_local", false)
}

pub fn reciprocal_rank_fusion(
    dense_rank: usize,
    lexical_rank: usize,
    k: usize,
    temporal_bonus: f64,
) -> f64 {
    let d = dense_rank.max(1) as f64;
    let l = lexical_rank.max(1) as f64;
    let kk = k.max(1) as f64;
    let score = (1.0 / (kk + d)) + (1.0 / (kk + l)) + temporal_bonus;
    (score * 1_000_000.0).round() / 1_000_000.0
}

pub fn evaluate_hallucination_gate(
    evidence_quality: f64,
    citation_coverage: f64,
    normalized_logprob: f64,
    semantic_entropy_inverse: f64,
    self_consistency: f64,
) -> (f64, &'static str) {
    fuse_socrates_confidence(
        evidence_quality,
        citation_coverage,
        normalized_logprob,
        semantic_entropy_inverse,
        self_consistency,
    )
}

pub fn enforce_fleet_profitability_guard(
    gross_revenue_nano: i64,
    llm_spend_nano: i64,
    infra_spend_nano: i64,
    is_guest: bool,
) -> (i64, f64, &'static str, &'static str) {
    let net_profit_nano = gross_revenue_nano - llm_spend_nano - infra_spend_nano;
    let denom = gross_revenue_nano.max(1) as f64;
    let net_margin_pct = (((net_profit_nano as f64) / denom) * 10000.0).round() / 100.0;
    if is_guest {
        return (
            net_profit_nano,
            net_margin_pct,
            "free_or_local",
            "guest_sybil_cloud_spend_block",
        );
    }
    if net_margin_pct < 35.0 {
        return (
            net_profit_nano,
            net_margin_pct,
            "free_or_local",
            "margin_leak_enact_cost_lever",
        );
    }
    (
        net_profit_nano,
        net_margin_pct,
        "balanced_production",
        "healthy_margin_floor",
    )
}

pub fn evaluate_wcag_contrast_ratio(fg_luminance: f64, bg_luminance: f64) -> (f64, bool, bool) {
    let lighter = fg_luminance.max(bg_luminance).max(0.0);
    let darker = fg_luminance.min(bg_luminance).max(0.0);
    let ratio = (((lighter + 0.05) / (darker + 0.05)) * 100.0).round() / 100.0;
    (ratio, ratio >= 4.5, ratio >= 7.0)
}

pub fn evaluate_fleet_health_and_focus(
    active_users: u32,
    net_margin_pct: f64,
    error_rate_pct: f64,
) -> (&'static str, bool) {
    if error_rate_pct > 2.0 {
        return ("reliability_incident_mitigation", false);
    }
    if net_margin_pct < 35.0 {
        return ("margin_leak_enact_cost_lever", false);
    }
    if active_users >= 100 && net_margin_pct >= 50.0 {
        return ("scale_winner_invest_growth", true);
    }
    ("steady_maintenance_observability", true)
}

pub fn step_force_directed_layout(
    dx: f64,
    dy: f64,
    ideal_dist: f64,
    damping: f64,
) -> (f64, f64, f64) {
    let dist = (dx * dx + dy * dy).sqrt().max(1.0);
    let force = (dist - ideal_dist) * 0.05;
    let vx = (((dx / dist) * force * damping) * 10000.0).round() / 10000.0;
    let vy = (((dy / dist) * force * damping) * 10000.0).round() / 10000.0;
    (vx, vy, (dist * 10000.0).round() / 10000.0)
}
